import { requireAdmin } from "@/lib/dal";
import { prisma } from "@/lib/prisma";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { VendorReviewActions } from "@/components/admin/vendor-review-actions";
export default async function AdminVendorsPage() { await requireAdmin(); const vendors = await prisma.vendor.findMany({ where: { status: "PENDING" }, include: { organization: { include: { kycCases: { include: { documents: true }, orderBy: { createdAt: "desc" }, take: 1 } } } }, orderBy: { createdAt: "asc" } }); return <main className="mx-auto flex max-w-6xl flex-col gap-6"><div><p className="text-sm text-muted-foreground">Marketplace compliance</p><h1 className="text-3xl font-semibold">Vendor review</h1><p className="mt-2 text-muted-foreground">Review pending applications and their KYC submissions.</p></div>{vendors.length === 0 ? <Card><CardContent className="p-8 text-sm text-muted-foreground">No pending vendor applications.</CardContent></Card> : <div className="grid gap-4">{vendors.map((vendor) => { const kyc = vendor.organization.kycCases[0]; return <Card key={vendor.id}><CardHeader><CardTitle className="flex flex-wrap items-center justify-between gap-3"><span>{vendor.businessName}</span><Badge>{vendor.status}</Badge></CardTitle></CardHeader><CardContent className="flex flex-col gap-4"><div className="grid gap-2 text-sm sm:grid-cols-2"><p><span className="text-muted-foreground">Contact:</span> {vendor.contactPerson}</p><p><span className="text-muted-foreground">Email:</span> {vendor.email}</p><p><span className="text-muted-foreground">Phone:</span> {vendor.phone}</p><p><span className="text-muted-foreground">Documents:</span> {kyc?.documents.length || 0}</p></div><VendorReviewActions kycCaseId={kyc?.id || ""} /></CardContent></Card>; })}</div>}</main>; }
